import{_ as o,o as r,c as n,a4 as t}from"./chunks/framework.B-wJupoK.js";const h=JSON.parse('{"title":"UI Design System - Executive Minimal","description":"","frontmatter":{},"headers":[],"relativePath":"design-system.md","filePath":"design-system.md","lastUpdated":1776517356000,"__rawMarkdown":"# UI Design System - Executive Minimal\\n\\n本设计规范（Executive Minimal）专为追求专业、严谨与高级感的企业级应用设计。整体风格采用“行政极简”理念，通过黑白灰中性色调、克制的圆角（2px）、严谨的字体层级以及扁平化的交互反馈，传达出稳重、信任与极致效率的品牌调性。\\n\\n## 1. 颜色规范 (Color Palette)\\n\\n系统放弃了高饱和度的彩色，转而使用极具层次感的黑白灰中性色系。\\n\\n### 亮色模式 (Light Mode)\\n- **主色 (Primary):** `#171717` (Almost Black) - 用于主要文本、主要按钮背景、标题。\\n- **辅助色 (Secondary):** `#F5F5F5` (Soft Silver) - 用于卡片悬浮背景、装饰性图标背景。\\n- **表面色 (Surface):** `#FFFFFF` (Pure White) - 用于卡片、弹出层、下拉菜单。\\n- **背景色 (Background):** `#FAFAFA` (Off White) - 用于页面大面积背景。\\n- **边框色 (Border):** `rgba(0,0,0,0.1)` - 用于分割线、卡片边框。\\n- **文本辅助色 (Text Light):** `#525252` - 用于次要说明、时间戳、副标题。\\n\\n### 暗色模式 (Dark Mode)\\n- **主色 (Primary):** `#FAFAFA` - 用于主要文本、主要按钮背景。\\n- **辅助色 (Secondary):** `#171717` - 用于卡片悬浮背景。\\n- **表面色 (Surface):** `#171717` - 用于卡片表面。\\n- **背景色 (Background):** `#0A0A0A` - 用于页面大面积深色背景。\\n- **边框色 (Border):** `rgba(255,255,255,0.1)` - 用于深色模式下的边界勾勒。\\n\\n## 2. 圆角与边框 (Radius & Borders)\\n\\n摒弃了常见的 6px/8px 大圆角，采用极简的微小圆角，营造严谨的“切割感”。\\n\\n- **统一圆角规范:** `--theme-radius: 2px`\\n- **适用组件:** 按钮、卡片、输入框、提示框、图片、头像等所有容器元素。\\n- **边框规范:** 默认采用 `1px solid var(--vp-c-border)` 进行物理分割，极少依赖大面积阴影。\\n\\n## 3. 字体层级 (Typography)\\n\\n字体排版强调清晰的结构和紧凑的字符间距，呈现出印刷级别的专业感。\\n\\n- **基础字体族:** `\'Inter\', -apple-system, BlinkMacSystemFont, \\"Helvetica Neue\\", sans-serif`\\n- **大标题 (H1):** `font-size: 3.8rem; font-weight: 700; letter-spacing: -0.03em;`\\n- **次级标题 (H2):** `font-size: 1.75rem; font-weight: 600; letter-spacing: -0.02em;`\\n- **正文 (Body):** `font-size: 1rem; font-weight: 400; letter-spacing: -0.01em; line-height: 1.7;`\\n- **小字说明 (Caption):** `font-size: 0.85rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.01em;`\\n\\n## 4. 阴影规范 (Shadows)\\n\\n阴影被降至最低限度，主要依赖物理边框进行层级划分。\\n\\n- **默认态:** `box-shadow: none;` (大部分卡片和按钮默认无阴影)\\n- **悬浮态 (Hover):** `--vp-shadow-1: 0 1px 2px 0 rgba(0, 0, 0, 0.05);` (极轻微的抬升感)\\n- **弹出层 (Dropdown/Modal):** `--vp-shadow-4: 0 20px 25px -5px rgba(0, 0, 0, 0.05);`\\n\\n## 5. 组件规范 (Components)\\n\\n### 按钮 (Buttons)\\n- **Primary 按钮:** 黑底白字（亮色模式），2px圆角，悬浮时背景加深且不带有位移放大动画（去浮躁感）。\\n- **Secondary 按钮:** 透明背景，1px 边框，黑字，悬浮时变为深底白字。\\n- **文字按钮 (Link):** 带有微小的大写转化与紧凑字间距，表现得更像标签。\\n\\n### 荣誉与风采轮播 (Honor Swiper)\\n- **容器:** 采用无边框设计，横向滚动隐藏滚动条 (`scrollbar-width: none`)。\\n- **卡片 (Slide):** `width: 320px; border: 1px solid var(--vp-c-border); border-radius: 2px;`\\n- **图片处理:** 默认附带 `filter: grayscale(15%);` 降低饱和度，鼠标悬浮时恢复全彩 `grayscale(0%)` 并伴随 `1.02` 比例的轻微放大，增强互动感而不失庄重。\\n\\n### 图片与头像\\n- **头像:** 采用方形或 `2px` 圆角，取代常见的纯圆形头像，呼应整体“严谨”的几何风格。\\n- **展示图:** 去除花哨的圆角，默认带有 1px 的边框约束，限制色彩外溢。\\n\\n## 6. 多端一致性测试标准 (Responsive Testing)\\n- **Desktop (>1024px):** 保证网格 (Grid) 结构完整，大标题的字间距展现印刷排版质感。\\n- **Tablet (768px - 1024px):** 两列卡片布局，导航栏保证模糊效果 (`backdrop-filter: blur`) 的性能。\\n- **Mobile (<768px):** \\n  - 核心间距从 `3rem` 缩减为 `2rem`。\\n  - Hero 标题字号缩小至 `2.8rem`。\\n  - 左右内边距保持 `24px`，避免贴边。\\n  - `HonorSwiper` 等横向滚动容器在移动端天然支持原生滚动阻尼 (`scroll-snap-type: x mandatory`)。\\n\\n---\\n*设计规范版本：v1.0 (Executive Minimal)*\\n*生成日期：2026-04-18*\\n"}'),i={name:"design-system.md"};function a(s,e,l,d,c,p){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="ui-design-system-executive-minimal" tabindex="-1">UI Design System - Executive Minimal <a class="header-anchor" href="#ui-design-system-executive-minimal" aria-label="Permalink to &quot;UI Design System - Executive Minimal&quot;">​</a></h1><p>本设计规范（Executive Minimal）专为追求专业、严谨与高级感的企业级应用设计。整体风格采用“行政极简”理念，通过黑白灰中性色调、克制的圆角（2px）、严谨的字体层级以及扁平化的交互反馈，传达出稳重、信任与极致效率的品牌调性。</p><h2 id="_1-颜色规范-color-palette" tabindex="-1">1. 颜色规范 (Color Palette) <a class="header-anchor" href="#_1-颜色规范-color-palette" aria-label="Permalink to &quot;1. 颜色规范 (Color Palette)&quot;">​</a></h2><p>系统放弃了高饱和度的彩色，转而使用极具层次感的黑白灰中性色系。</p><h3 id="亮色模式-light-mode" tabindex="-1">亮色模式 (Light Mode) <a class="header-anchor" href="#亮色模式-light-mode" aria-label="Permalink to &quot;亮色模式 (Light Mode)&quot;">​</a></h3><ul><li><strong>主色 (Primary):</strong> <code>#171717</code> (Almost Black) - 用于主要文本、主要按钮背景、标题。</li><li><strong>辅助色 (Secondary):</strong> <code>#F5F5F5</code> (Soft Silver) - 用于卡片悬浮背景、装饰性图标背景。</li><li><strong>表面色 (Surface):</strong> <code>#FFFFFF</code> (Pure White) - 用于卡片、弹出层、下拉菜单。</li><li><strong>背景色 (Background):</strong> <code>#FAFAFA</code> (Off White) - 用于页面大面积背景。</li><li><strong>边框色 (Border):</strong> <code>rgba(0,0,0,0.1)</code> - 用于分割线、卡片边框。</li><li><strong>文本辅助色 (Text Light):</strong> <code>#525252</code> - 用于次要说明、时间戳、副标题。</li></ul><h3 id="暗色模式-dark-mode" tabindex="-1">暗色模式 (Dark Mode) <a class="header-anchor" href="#暗色模式-dark-mode" aria-label="Permalink to &quot;暗色模式 (Dark Mode)&quot;">​</a></h3><ul><li><strong>主色 (Primary):</strong> <code>#FAFAFA</code> - 用于主要文本、主要按钮背景。</li><li><strong>辅助色 (Secondary):</strong> <code>#171717</code> - 用于卡片悬浮背景。</li><li><strong>表面色 (Surface):</strong> <code>#171717</code> - 用于卡片表面。</li><li><strong>背景色 (Background):</strong> <code>#0A0A0A</code> - 用于页面大面积深色背景。</li><li><strong>边框色 (Border):</strong> <code>rgba(255,255,255,0.1)</code> - 用于深色模式下的边界勾勒。</li></ul><h2 id="_2-圆角与边框-radius-borders" tabindex="-1">2. 圆角与边框 (Radius &amp; Borders) <a class="header-anchor" href="#_2-圆角与边框-radius-borders" aria-label="Permalink to &quot;2. 圆角与边框 (Radius &amp; Borders)&quot;">​</a></h2><p>摒弃了常见的 6px/8px 大圆角，采用极简的微小圆角，营造严谨的“切割感”。</p><ul><li><strong>统一圆角规范:</strong> <code>--theme-radius: 2px</code></li><li><strong>适用组件:</strong> 按钮、卡片、输入框、提示框、图片、头像等所有容器元素。</li><li><strong>边框规范:</strong> 默认采用 <code>1px solid var(--vp-c-border)</code> 进行物理分割，极少依赖大面积阴影。</li></ul><h2 id="_3-字体层级-typography" tabindex="-1">3. 字体层级 (Typography) <a class="header-anchor" href="#_3-字体层级-typography" aria-label="Permalink to &quot;3. 字体层级 (Typography)&quot;">​</a></h2><p>字体排版强调清晰的结构和紧凑的字符间距，呈现出印刷级别的专业感。</p><ul><li><strong>基础字体族:</strong> <code>&#39;Inter&#39;, -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, sans-serif</code></li><li><strong>大标题 (H1):</strong> <code>font-size: 3.8rem; font-weight: 700; letter-spacing: -0.03em;</code></li><li><strong>次级标题 (H2):</strong> <code>font-size: 1.75rem; font-weight: 600; letter-spacing: -0.02em;</code></li><li><strong>正文 (Body):</strong> <code>font-size: 1rem; font-weight: 400; letter-spacing: -0.01em; line-height: 1.7;</code></li><li><strong>小字说明 (Caption):</strong> <code>font-size: 0.85rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.01em;</code></li></ul><h2 id="_4-阴影规范-shadows" tabindex="-1">4. 阴影规范 (Shadows) <a class="header-anchor" href="#_4-阴影规范-shadows" aria-label="Permalink to &quot;4. 阴影规范 (Shadows)&quot;">​</a></h2><p>阴影被降至最低限度，主要依赖物理边框进行层级划分。</p><ul><li><strong>默认态:</strong> <code>box-shadow: none;</code> (大部分卡片和按钮默认无阴影)</li><li><strong>悬浮态 (Hover):</strong> <code>--vp-shadow-1: 0 1px 2px 0 rgba(0, 0, 0, 0.05);</code> (极轻微的抬升感)</li><li><strong>弹出层 (Dropdown/Modal):</strong> <code>--vp-shadow-4: 0 20px 25px -5px rgba(0, 0, 0, 0.05);</code></li></ul><h2 id="_5-组件规范-components" tabindex="-1">5. 组件规范 (Components) <a class="header-anchor" href="#_5-组件规范-components" aria-label="Permalink to &quot;5. 组件规范 (Components)&quot;">​</a></h2><h3 id="按钮-buttons" tabindex="-1">按钮 (Buttons) <a class="header-anchor" href="#按钮-buttons" aria-label="Permalink to &quot;按钮 (Buttons)&quot;">​</a></h3><ul><li><strong>Primary 按钮:</strong> 黑底白字（亮色模式），2px圆角，悬浮时背景加深且不带有位移放大动画（去浮躁感）。</li><li><strong>Secondary 按钮:</strong> 透明背景，1px 边框，黑字，悬浮时变为深底白字。</li><li><strong>文字按钮 (Link):</strong> 带有微小的大写转化与紧凑字间距，表现得更像标签。</li></ul><h3 id="荣誉与风采轮播-honor-swiper" tabindex="-1">荣誉与风采轮播 (Honor Swiper) <a class="header-anchor" href="#荣誉与风采轮播-honor-swiper" aria-label="Permalink to &quot;荣誉与风采轮播 (Honor Swiper)&quot;">​</a></h3><ul><li><strong>容器:</strong> 采用无边框设计，横向滚动隐藏滚动条 (<code>scrollbar-width: none</code>)。</li><li><strong>卡片 (Slide):</strong> <code>width: 320px; border: 1px solid var(--vp-c-border); border-radius: 2px;</code></li><li><strong>图片处理:</strong> 默认附带 <code>filter: grayscale(15%);</code> 降低饱和度，鼠标悬浮时恢复全彩 <code>grayscale(0%)</code> 并伴随 <code>1.02</code> 比例的轻微放大，增强互动感而不失庄重。</li></ul><h3 id="图片与头像" tabindex="-1">图片与头像 <a class="header-anchor" href="#图片与头像" aria-label="Permalink to &quot;图片与头像&quot;">​</a></h3><ul><li><strong>头像:</strong> 采用方形或 <code>2px</code> 圆角，取代常见的纯圆形头像，呼应整体“严谨”的几何风格。</li><li><strong>展示图:</strong> 去除花哨的圆角，默认带有 1px 的边框约束，限制色彩外溢。</li></ul><h2 id="_6-多端一致性测试标准-responsive-testing" tabindex="-1">6. 多端一致性测试标准 (Responsive Testing) <a class="header-anchor" href="#_6-多端一致性测试标准-responsive-testing" aria-label="Permalink to &quot;6. 多端一致性测试标准 (Responsive Testing)&quot;">​</a></h2><ul><li><strong>Desktop (&gt;1024px):</strong> 保证网格 (Grid) 结构完整，大标题的字间距展现印刷排版质感。</li><li><strong>Tablet (768px - 1024px):</strong> 两列卡片布局，导航栏保证模糊效果 (<code>backdrop-filter: blur</code>) 的性能。</li><li><strong>Mobile (&lt;768px):</strong><ul><li>核心间距从 <code>3rem</code> 缩减为 <code>2rem</code>。</li><li>Hero 标题字号缩小至 <code>2.8rem</code>。</li><li>左右内边距保持 <code>24px</code>，避免贴边。</li><li><code>HonorSwiper</code> 等横向滚动容器在移动端天然支持原生滚动阻尼 (<code>scroll-snap-type: x mandatory</code>)。</li></ul></li></ul><hr><p><em>设计规范版本：v1.0 (Executive Minimal)</em><em>生成日期：2026-04-18</em></p>',28)])])}const m=o(i,[["render",a]]);export{h as __pageData,m as default};
